import{_ as o,o as t,c as r,a0 as n}from"./chunks/framework.DNNiP2TX.js";const l=JSON.parse('{"title":"@shutter-network/concorde/password-auth routes","description":"","frontmatter":{"title":"@shutter-network/concorde/password-auth routes"},"headers":[],"relativePath":"reference/routes/password-auth.md","filePath":"reference/routes/password-auth.md"}'),s={name:"reference/routes/password-auth.md"};function a(d,e,i,c,h,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="shutter-network-concorde-password-auth" tabindex="-1">@shutter-network/concorde/password-auth <a class="header-anchor" href="#shutter-network-concorde-password-auth" aria-label="Permalink to &quot;@shutter-network/concorde/password-auth&quot;">​</a></h1><p>The HTTP routes this component serves: 4 on the Public server.</p><p><strong>Every path is relative.</strong> Each one is printed as the plugin declares it, under whatever prefix the component&#39;s constructor registers that plugin at. This page states no mount point, because the constructor is where the mount point is decided.</p><p>Generated from what the route plugins in <code>src/password-auth/routes.ts</code> declare, which is what a running Gateway serves at <code>GET /openapi.json</code>. Never edited by hand.</p><h2 id="public-server" tabindex="-1">Public server <a class="header-anchor" href="#public-server" aria-label="Permalink to &quot;Public server&quot;">​</a></h2><p><strong>The Public server is what a User&#39;s client calls.</strong> Which credential each route wants, and which wants none, is in that route&#39;s own description below.</p><h3 id="put-password" tabindex="-1"><code>PUT /password</code> <a class="header-anchor" href="#put-password" aria-label="Permalink to &quot;`PUT /password`&quot;">​</a></h3><p><strong>Replace the authenticated User&#39;s password</strong></p><p>A User rotating their own credential by proving they hold the current one. There is <strong>no <code>user</code> field</strong>: the User is the one the Gateway authenticated. So no request can change another User&#39;s password, and there is no check to get wrong. There is no recovery path either. Proving identity <em>without</em> the credential is what this framework declined to build. A forgotten password is replaced by the Operator&#39;s own trusted code, or not at all.</p><p>A User who holds no password cannot get one here, having nothing to prove, and is refused with the same 401 a wrong one gets. A changed password <strong>revokes nothing</strong>: a User who changed theirs out of fear is served by <code>DELETE /auth/tokens</code>, which is one request away. <strong>Requires a bearer Token</strong>, presented as <code>Authorization: Bearer &lt;token&gt;</code> and obtained from <code>POST /auth/tokens</code>. The User acted on is the one the Gateway authenticated, and no parameter anywhere names another. These routes take no query parameters at all. A credential travels in the body or in the Authorization header, never in a URL. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Authentication</code>.</p><p><strong>Request body</strong></p><p><code>application/json</code>, required.</p><ul><li><strong><code>currentPassword</code></strong> <code>string</code>, required, 1 to 1024 characters</li><li><strong><code>newPassword</code></strong> <code>string</code>, required, 1 to 1024 characters</li></ul><p><strong>Responses</strong></p><p><strong><code>204</code></strong> with no body</p><p>The password is replaced. Every Token issued before it, the presented one included, still works.</p><p><strong><code>400</code></strong> <code>application/json</code></p><p>A password is missing, empty or longer than 1024 characters, or a query parameter was written. A <code>user</code> field in the body is not refused: it is stripped before the handler and reaches nothing.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>401</code></strong> <code>application/json</code></p><p>Authentication failed, which is the whole of what is said: a wrong password, an id nobody holds, a User with no password, and a Token that is missing, malformed, unknown or expired are one status and one message, so nothing here answers who exists.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h3 id="delete-tokens" tabindex="-1"><code>DELETE /tokens</code> <a class="header-anchor" href="#delete-tokens" aria-label="Permalink to &quot;`DELETE /tokens`&quot;">​</a></h3><p><strong>Revoke every Token of the authenticated User</strong></p><p>The answer to &quot;I think I have been compromised&quot;, and the only one there is. Nothing removes a User, so every credential of this scheme that stops working before it expires stops working here. Every Token of the authenticated User goes, <strong>including the one presented</strong>, so the caller is logged out too. It is the only compaction a User has over their own row count, because nothing reaps an expired Token.</p><p>It drops no password and no credential of any other scheme, so a User who is also reached another way keeps that way. <strong>Requires a bearer Token</strong>, presented as <code>Authorization: Bearer &lt;token&gt;</code> and obtained from <code>POST /auth/tokens</code>. The User acted on is the one the Gateway authenticated, and no parameter anywhere names another. These routes take no query parameters at all. A credential travels in the body or in the Authorization header, never in a URL. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Authentication</code>.</p><p><strong>Responses</strong></p><p><strong><code>204</code></strong> with no body</p><p>Every Token that User held, including the presented one, has stopped working.</p><p><strong><code>400</code></strong> <code>application/json</code></p><p>A query parameter was written, and these routes take none.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>401</code></strong> <code>application/json</code></p><p>Authentication failed, which is the whole of what is said: a wrong password, an id nobody holds, a User with no password, and a Token that is missing, malformed, unknown or expired are one status and one message, so nothing here answers who exists.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h3 id="post-tokens" tabindex="-1"><code>POST /tokens</code> <a class="header-anchor" href="#post-tokens" aria-label="Permalink to &quot;`POST /tokens`&quot;">​</a></h3><p><strong>Trade a password for a Token</strong></p><p>A User&#39;s own opaque id and their password, for a bearer Token to present on everything else. <strong>This response is the only place the Token&#39;s plaintext ever exists.</strong> It is stored as a digest and cannot be read back. A client that loses it logs in again rather than recovering it.</p><p>This is the one route here that requires no Token, and the one a client calls first. These routes take no query parameters at all. A credential travels in the body or in the Authorization header, never in a URL. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Authentication</code>.</p><p><strong>Request body</strong></p><p><code>application/json</code>, required.</p><ul><li><strong><code>user</code></strong> <code>string</code>, required, matching <code>^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$</code></li><li><strong><code>password</code></strong> <code>string</code>, required, 1 to 1024 characters</li></ul><p><strong>Responses</strong></p><p><strong><code>201</code></strong> <code>application/json</code></p><p>The Token, when it stops working, and the User it belongs to, so that a client needs no second request to know who it is.</p><ul><li><p><strong><code>token</code></strong> <code>string</code>, required</p></li><li><p><strong><code>expiresAt</code></strong> <code>string</code>, required</p><p>When the Token stops working, ISO 8601. Always present: a Token that never expires is unrepresentable, and the lifetime is the Gateway&#39;s rather than the client&#39;s to choose. Nothing renews a Token and nothing reaps an expired one: it simply stops being accepted, and a client past this time logs in again.</p></li><li><p><strong><code>user</code></strong> <code>object</code>, required</p><ul><li><p><strong><code>id</code></strong> <code>string</code>, required</p></li><li><p><strong><code>attributes</code></strong> any JSON, required</p><p>Arbitrary JSON, defined by the deployment and interpreted by nothing in the Gateway. This is where grouping and therefore authorization live. Nothing on this surface can write them: a password names a User who already exists.</p></li><li><p><strong><code>createdAt</code></strong> <code>string</code>, required</p></li></ul></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p>The <code>user</code> is not a uuid, or the password is missing, empty or longer than 1024 characters. A well-formed id nobody holds is a 401 and not a 400, since a 400 would answer who exists.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>401</code></strong> <code>application/json</code></p><p>Authentication failed, which is the whole of what is said: a wrong password, an id nobody holds, a User with no password, and a Token that is missing, malformed, unknown or expired are one status and one message, so nothing here answers who exists.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h3 id="delete-tokens-current" tabindex="-1"><code>DELETE /tokens/current</code> <a class="header-anchor" href="#delete-tokens-current" aria-label="Permalink to &quot;`DELETE /tokens/current`&quot;">​</a></h3><p><strong>Revoke the presented Token</strong></p><p>Logging out. The presented Token stops working, and no other Token of this User&#39;s does. So a Token on a device they no longer trust is droppable from a device they still use. Idempotent: the row is gone afterwards, whether or not this call removed it.</p><p>It acts on the Token in the <code>Authorization</code> header and on nothing else, so a request the Gateway authenticated by some other scheme answers 204 and drops nothing. <strong>Requires a bearer Token</strong>, presented as <code>Authorization: Bearer &lt;token&gt;</code> and obtained from <code>POST /auth/tokens</code>. The User acted on is the one the Gateway authenticated, and no parameter anywhere names another. These routes take no query parameters at all. A credential travels in the body or in the Authorization header, never in a URL. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Authentication</code>.</p><p><strong>Responses</strong></p><p><strong><code>204</code></strong> with no body</p><p>The Token no longer works. Nothing is answered, including how many Tokens there were: a count is a number about Tokens the caller does not hold.</p><p><strong><code>400</code></strong> <code>application/json</code></p><p>A query parameter was written, and these routes take none.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>401</code></strong> <code>application/json</code></p><p>Authentication failed, which is the whole of what is said: a wrong password, an id nobody holds, a User with no password, and a Token that is missing, malformed, unknown or expired are one status and one message, so nothing here answers who exists.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul>',69)])])}const u=o(s,[["render",a]]);export{l as __pageData,u as default};
